+	}
+	want := newProjectionDoc(kind, resultpipeline.TransitionCandidate{
+		BuildResult: resultpipeline.BuildResult{EvaluatedAt: evaluatedAt},
+		Receipt:     receipt,
+	}, next)
+	wb, err := closureprotocol.CanonicalJSON(want)
+	if err != nil {
+		return err
+	}
+	if string(wb) != string(data) {
